-- =============================================================================
-- Volcado inicial: catálogo cliente/intermediario + saldos CC desde Excel
-- GENERADO por scripts/generar-sql-vuelco-inicial.js — no editar a mano; regenerar con:
--   npm run sql:vuelco-inicial
--   VUELCO_USUARIO_EMAIL=... VUELCO_MONEDA_SALDO=USD|ARS|EUR npm run sql:vuelco-inicial
-- Origen: docs/Vuelco_Inicial.xlsx
-- Hoja: primera solapa; A=Cliente, B=Saldo, C=Cliente o Intermediario
-- Convención producto: importes en USD (columna Saldo).
-- Moneda movimientos CC: USD
-- usuario_id: auth.users ← lucas.bustos.martin@gmail.com
-- Pagador/cobrador manual: saldo<0 → pagador entidad + cobrador empresa; saldo>0 → pagador empresa + cobrador entidad.
-- =============================================================================
-- PELIGRO: borra órdenes, transacciones, CC, caja y catálogos cliente/intermediario.
-- Requiere public.fecha_hoy_argentina() y que el usuario exista en Auth.
-- =============================================================================

BEGIN;

-- Borrado previo de saldos de un volcado Excel anterior (mismo texto de concepto).
-- Útil si ajustás el script y no truncás CC; tras TRUNCATE completo no borra filas.
DELETE FROM public.movimientos_cuenta_corriente
  WHERE es_movimiento_manual IS TRUE AND concepto LIKE 'Saldo inicial (volcado Excel)%';
DELETE FROM public.movimientos_cuenta_corriente_intermediario
  WHERE es_movimiento_manual IS TRUE AND concepto LIKE 'Saldo inicial (volcado Excel)%';

TRUNCATE TABLE public.movimientos_cuenta_corriente CASCADE;
TRUNCATE TABLE public.movimientos_cuenta_corriente_intermediario CASCADE;
TRUNCATE TABLE public.movimientos_caja CASCADE;

DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'orden_comisiones_generadas') THEN
    EXECUTE 'TRUNCATE TABLE public.orden_comisiones_generadas CASCADE';
  END IF;
END $$;

TRUNCATE TABLE public.transacciones CASCADE;
TRUNCATE TABLE public.comisiones_orden CASCADE;
TRUNCATE TABLE public.instrumentacion CASCADE;
TRUNCATE TABLE public.ordenes CASCADE;

TRUNCATE TABLE public.clientes CASCADE;
TRUNCATE TABLE public.intermediarios CASCADE;

-- Secuencias de número interno (si existen)
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM pg_sequences WHERE schemaname = 'public' AND sequencename = 'ordenes_numero_seq') THEN
    PERFORM setval('public.ordenes_numero_seq', 1, false);
  END IF;
  IF EXISTS (SELECT 1 FROM pg_sequences WHERE schemaname = 'public' AND sequencename = 'transacciones_numero_seq') THEN
    PERFORM setval('public.transacciones_numero_seq', 1, false);
  END IF;
END $$;

